import { createChatOrchestrator } from './chatOrchestrator.js';
import type { AIProvider, MessageChunk } from '../types/ai.js';
import { PromptBuilder } from '../infrastructure/builders/promptBuilder.js';
import type { ChatSession } from '../types/session.js';

const promptBuilder = new PromptBuilder({ identity: 'You are a test assistant.' });

const createSession = (content: string): ChatSession => ({
  sessionId: 's1',
  userId: 'u1',
  entries: [{ role: 'user', content, timestamp: new Date().toISOString() }],
});

const rejectingProvider = (reason: unknown): AIProvider => ({
  // eslint-disable-next-line require-yield
  async *sendMessage(): AsyncGenerator<MessageChunk> {
    throw reason;
  },
  async generateStructured<T>(): Promise<T> {
    return {} as T;
  },
});

describe('ChatOrchestrator onError with non-Error rejections', () => {
  it('calls onError with a coerced Error when a string is thrown', async () => {
    let receivedError: Error | undefined;
    const hooks = {
      onError: async (_session: ChatSession, error: Error) => {
        receivedError = error;
      },
    };

    const orchestrator = createChatOrchestrator(
      rejectingProvider('string boom'),
      promptBuilder,
      undefined,
      { hooks }
    );

    try {
      await orchestrator.processMessage(createSession('hello'));
    } catch (e) {
      // Expected to throw
    }

    expect(receivedError).toBeInstanceOf(Error);
    expect(receivedError?.message).toBe('string boom');
  });
});

