    );

    try {
      await orchestrator.processMessage(createSession('hello'));
    } catch (e) {
      // Expected to throw
    }

    expect(receivedError).toBeInstanceOf(Error);
    expect(receivedError?.message).toBe('string boom');
  });

  it('calls onError with a coerced Error when a plain object is thrown', async () => {
    let receivedError: Error | undefined;
    const hooks = {
      onError: async (_session: ChatSession, error: Error) => {
        receivedError = error;
      },
    };

    const reason = { code: 503, detail: 'upstream down' };
    const orchestrator = createChatOrchestrator(
      rejectingProvider(reason),
      promptBuilder,
      undefined,
      { hooks }
    );

    try {
      await orchestrator.processMessage(createSession('hello'));
    } catch (e) {
      // Expected to throw
    }

    expect(receivedError).toBeInstanceOf(Error);
    expect(receivedError?.cause).toBe(reason);
  });

  it('calls onError with a coerced Error when undefined is thrown', async () => {
